import Link from 'next/link';import { api } from '@/lib/api';
export default async function Dashboard(){const d=await api.dashboard();const stats=[['Total Tickets',d.total],['Open',d.open],['In Progress',d.inProgress],['Resolved',d.resolved]];return <><div className="mb-6 flex items-center justify-between"><div><h1 className="text-3xl font-black">Dashboard</h1><p className="text-slate-500">Support overview and recent activity.</p></div><Link className="btn btn-primary" href="/tickets/new">+ New Ticket</Link></div><section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{stats.map(([n,v])=><div className="card p-5" key={n}><p className="text-sm text-slate-500">{n}</p><p className="mt-2 text-3xl font-black">{v}</p></div>)}</section><section className="card mt-6 overflow-hidden"><div className="border-b p-5"><h2 className="text-xl font-bold">Recently Created</h2></div>{d.recent.length===0?<p className="p-6 text-slate-500">No tickets yet.</p>:<div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-slate-50"><tr>{['ID','Customer','Subject','Priority','Status','Created'].map(x=><th className="p-3" key={x}>{x}</th>)}</tr></thead><tbody>{d.recent.map(t=><tr className="border-t" key={t.id}><td className="p-3"><Link className="font-bold underline" href={`/tickets/${t.id}`}>#{t.id}</Link></td><td className="p-3">{t.customer_name}</td><td className="p-3">{t.subject}</td><td className="p-3"><span className="badge">{t.priority}</span></td><td className="p-3">{t.status}</td><td className="p-3">{new Date(t.created_at).toLocaleDateString()}</td></tr>)}</tbody></table></div>}</section></>}
