import { Agent,Page,Ticket } from '@/types'; const API=process.env.NEXT_PUBLIC_API_URL??'http://localhost:4000/api';
async function request<T>(path:string,init?:RequestInit):Promise<T>{const r=await fetch(`${API}${path}`,{...init,headers:{'Content-Type':'application/json',...(init?.headers??{})},cache:'no-store'});if(!r.ok){const b=await r.json().catch(()=>({message:'Request failed'})) as {message?:string};throw new Error(b.message??'Request failed');}return r.json() as Promise<T>}
export const api={dashboard:()=>request<{total:number;open:number;inProgress:number;resolved:number;recent:Ticket[]}>('/dashboard'),agents:()=>request<Agent[]>('/agents'),tickets:(q:string)=>request<Page<Ticket>>(`/tickets?${q}`),ticket:(id:string|number)=>request<Ticket>(`/tickets/${id}`),create:(body:object)=>request<Ticket>('/tickets',{method:'POST',body:JSON.stringify(body)}),update:(id:number,body:object)=>request<Ticket>(`/tickets/${id}`,{method:'PUT',body:JSON.stringify(body)}),assign:(id:number,agentId:number)=>request<Ticket>(`/tickets/${id}/assign`,{method:'PATCH',body:JSON.stringify({agentId})}),status:(id:number,status:string)=>request<Ticket>(`/tickets/${id}/status`,{method:'PATCH',body:JSON.stringify({status})}),delete:(id:number)=>request<{message:string}>(`/tickets/${id}`,{method:'DELETE'})};
